    # Check if the graph is bipartite
    color = [-1] * (n + 1)

    def is_bipartite(node, c):
        color[node] = c
        for neighbor in adj_list[node]:
            if color[neighbor] == -1:
                if not is_bipartite(neighbor, 1 - c):
                    return False
            elif color[neighbor] == c:
                return False
        return True

